	if err != nil {
		t.Fatalf("NewClient error: %v", err)
	}

	ok, err := client.CallLogs.AddRecording(
		context.Background(),
		CallLogID("log-1"),
		"recording.mp3",
		bytes.NewReader(audio),
		WithCallLogsRequestOptions(pipedrive.WithHeader("X-Test", "recording")),
	)
