// opaqueReader is not one of the reader types http.NewRequest recognizes,
// so requests built from it get no GetBody unless the client buffers it.
type opaqueReader struct{ io.Reader }

func fastRetryPolicy() RetryPolicy {
	return RetryPolicy{
		MaxAttempts:     3,
		BaseDelay:       time.Millisecond,
		MaxDelay:        time.Millisecond,
		Jitter:          func(d time.Duration) time.Duration { return d },
		RetryAllMethods: true,
	}
}

func TestRawClient_Do_RetriesReaderBodyOn429(t *testing.T) {
	t.Parallel()

	var bodies []string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Fatalf("read request body: %v", err)
		}
		bodies = append(bodies, string(body))
		if len(bodies) == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"message":"slow down"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(srv.Close)

	policy := fastRetryPolicy()
	httpClient := NewHTTPClient(Config{HTTPClient: srv.Client(), RetryPolicy: &policy})
	raw, err := NewRawClient(srv.URL, httpClient)
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	var out struct {
		Ok bool `json:"ok"`
	}
	body := opaqueReader{strings.NewReader("upload-payload")}
	if err := raw.Do(context.Background(), http.MethodPost, "/files", nil, body, &out); err != nil {
		t.Fatalf("Do error: %v", err)
	}
	if !out.Ok {
		t.Fatalf("expected ok=true")
	}
	if len(bodies) != 2 {
		t.Fatalf("expected 2 attempts, got %d", len(bodies))
	}
	if bodies[0] != "upload-payload" || bodies[1] != "upload-payload" {
		t.Fatalf("expected full payload on every attempt, got %q", bodies)
	}
}

func TestRawClient_Do_MakesReaderBodyReplayable(t *testing.T) {
	t.Parallel()

	var sawGetBody bool
	observer := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		sawGetBody = req.GetBody != nil
		return &http.Response{
			StatusCode: 200,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader(`{"ok":true}`)),
			Request:    req,
		}, nil
	})

	raw, err := NewRawClient("https://example.test", NewHTTPClient(Config{
		HTTPClient: &http.Client{Transport: observer},
	}))
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	if err := raw.Do(context.Background(), http.MethodPost, "/x", nil, opaqueReader{strings.NewReader("data")}, nil); err != nil {
		t.Fatalf("Do error: %v", err)
	}
	if !sawGetBody {
		t.Fatalf("expected request GetBody to be set for replayable reader body")
	}
}

func TestRawClient_Do_NoRetryLeavesReaderBodyStreaming(t *testing.T) {
	t.Parallel()

	var calls int
	var sawGetBody bool
	observer := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		sawGetBody = req.GetBody != nil
		return &http.Response{
			StatusCode: http.StatusTooManyRequests,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader(`{"message":"slow down"}`)),
			Request:    req,
		}, nil
	})

	policy := fastRetryPolicy()
	raw, err := NewRawClient("https://example.test", NewHTTPClient(Config{
		HTTPClient:  &http.Client{Transport: observer},
		RetryPolicy: &policy,
	}))
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	err = raw.Do(context.Background(), http.MethodPost, "/x", nil, opaqueReader{strings.NewReader("data")}, nil, WithNoRetry())
	var rlErr *RateLimitError
	if !errors.As(err, &rlErr) {
		t.Fatalf("expected RateLimitError, got %T (%v)", err, err)
	}
	if calls != 1 {
		t.Fatalf("expected 1 attempt with WithNoRetry, got %d", calls)
	}
	if sawGetBody {
		t.Fatalf("expected streaming body (no GetBody) when retries are disabled")
	}
}

func TestRawClient_Do_ReaderBodyReadError(t *testing.T) {
	t.Parallel()

	raw, err := NewRawClient("https://example.test", NewHTTPClient(Config{
		HTTPClient: &http.Client{Transport: roundTripperFunc(func(req *http.Request) (*http.Response, error) {
			t.Fatalf("unexpected request sent")
			return nil, nil
		})},
	}))
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	broken := opaqueReader{strings.NewReader("")}
	broken.Reader = nil
	err = raw.Do(context.Background(), http.MethodPost, "/x", nil, broken, nil)
	if err == nil {
		t.Fatalf("expected body read error")
	}
}

